package com.tura.ventas.service;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.tura.ventas.modelo.CategoriaProducto; import com.tura.ventas.repositorio.CategoriaProductoRepository;
@Service public class CategoriaProductoService { private final CategoriaProductoRepository r; public CategoriaProductoService(CategoriaProductoRepository r){this.r=r;} public List<CategoriaProducto> listar(){return r.findAll();} public CategoriaProducto obtener(Integer id){return r.findById(id).orElseThrow();} @Transactional public CategoriaProducto guardar(CategoriaProducto c){if(c.getNombre()==null||c.getNombre().isBlank())throw new IllegalArgumentException("Ingrese el nombre de la categoría."); return r.save(c);} @Transactional public void eliminar(Integer id){r.deleteById(id);} }
